using System;
using System.Collections;
using System.Collections.Generic;
using Astrea.GameStates;
using LittleLeo;
using LittleLeo.Events;
using UnityEngine;

namespace Astrea;

[CreateAssetMenu(fileName = "CorruptPlayerState", menuName = "Data/Battle/Game States/Corrupt Player State")]
public class CorruptPlayerState : GameState
{
	[Header("Active Enemies")]
	[SerializeField]
	private CurrentCorruptedAnimals currentCorruptedAnimals;

	[Header("Events")]
	[SerializeField]
	private VoidEvent OnEndCorruptPlayerState;

	[SerializeField]
	private VoidEvent OnStartCorruptPlayerState;

	[Header("Debug")]
	[SerializeField]
	private bool verbose;

	[NonSerialized]
	private bool stopEnemiesAttacks;

	[NonSerialized]
	private List<IEnumerator> enemiesActivations = new List<IEnumerator>();

	[NonSerialized]
	private bool isInit;

	private List<GameObject> activeCorruptedAnimals => currentCorruptedAnimals.activeCorruptedAnimals;

	public void OnReset()
	{
		enemiesActivations.Clear();
		stopEnemiesAttacks = false;
		isInit = false;
	}

	public void OnCorruptionSourcePurged()
	{
		stopEnemiesAttacks = true;
	}

	public override void OnStartState()
	{
		base.OnStartState();
		("EnemiesActivations: " + enemiesActivations.Count).DebugLogIfVerbose(verbose);
		GameStateManager instance = ReferenceSingleton<GameStateManager>.Instance;
		TurnManager instance2 = ReferenceSingleton<TurnManager>.Instance;
		if (!isInit)
		{
			ReferenceSingleton<CoroutineHandler>.Instance.Run(StartEnemiesTurn());
		}
		else if (stopEnemiesAttacks)
		{
			"Stop attacks".DebugLogIfVerbose(verbose);
			instance2.StartNextTurnWithNoActivations();
			instance.SetChooseActionState();
			isInit = false;
		}
		else if (enemiesActivations.Count > 0)
		{
			ActivateNextEnemyActivation();
		}
		else if (currentCorruptedAnimals.activeCorruptedAnimals.Count == 0)
		{
			instance2.StartNextTurnWithNoActivations();
			ReferenceSingleton<GameStateManager>.Instance.TryEnterEndPlayerTurnStateIfNotEndOfBattleStateAlreadyCalled();
			isInit = false;
		}
		else
		{
			"No more activations".DebugLogIfVerbose(verbose);
			OnEndCorruptPlayerState.Raise();
			instance2.StartNextTurn();
			isInit = false;
		}
	}

	private void ActivateNextEnemyActivation()
	{
		GameStateManager instance = ReferenceSingleton<GameStateManager>.Instance;
		"Activating Next Enemy Activation".DebugLogIfVerbose(verbose);
		instance.ActionsQueueState.EnqueueAction(enemiesActivations.PopFirst(), ignoreNextRunActionWaitForFramesOnMobile: true);
		instance.SetState(instance.ActionsQueueState);
	}

	private IEnumerator StartEnemiesTurn()
	{
		Debug.Log("============================== ENEMY TURN ==================================");
		enemiesActivations.Clear();
		stopEnemiesAttacks = false;
		isInit = true;
		("EnemiesActivations: " + enemiesActivations.Count).DebugLogIfVerbose(verbose);
		yield return new WaitForSeconds(0.8f);
		OnStartCorruptPlayerState.Raise();
		for (int i = 0; i < activeCorruptedAnimals.Count; i++)
		{
			CorruptedAnimalActivation component = activeCorruptedAnimals[i].GetComponent<CorruptedAnimalActivation>();
			enemiesActivations.Add(component.StartTurnActivation());
			if (component.BasicDiceSpawned)
			{
				enemiesActivations.Add(component.BasicDiceActivation());
				if (component.BoostDiceSpawned)
				{
					enemiesActivations.Add(component.BoostDiceActivation());
				}
			}
			enemiesActivations.Add(component.EndOfTurnActivation());
			enemiesActivations.Add(component.EndOfTurnResetActivation());
		}
		("EnemiesActivations: " + enemiesActivations.Count).DebugLogIfVerbose(verbose);
		ActivateNextEnemyActivation();
	}

	public override void OnEndState()
	{
	}
}
